window.AUTH=window.AUTH||{};window.AUTH["04-1527"]={"d":"04-1527","id":"2005/04-1527","n":"S.D. Warren Co. v. Maine Board of Environmental Protection","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"","url":"https://www.justice.gov/osg/media/227611/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/sd-warren-co-v-maine-bd-envtl-prot-amicus-merits","n":87}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep547/usrep547370/usrep547370.pdf","tr":true,"items":[{"t":"case","label":"Alabama Rivers Alliance v. FERC","cite":"325 F.3d 290","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/325/290/","by":{"0":"26"}},{"t":"case","label":"American Rivers, Inc. v. FERC","cite":"129 F.3d 99","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/129/99/","by":{"0":"26"}},{"t":"case","label":"Arizona v. California","cite":"373 U.S. 546","y":1963,"id":"1961/8_orig","sc":1,"op":1,"sum":"This original suit was brought in this Court by the State of Arizona against the State of California and seven of its public agencies. Later Nevada, New Mexico, Utah and the United States became parties. The basic controversy is over how much water each State has a legal right to use out of the waters of the Colorado River and its tributaries. A Special Master appointed by the Court conducted a lengthy trial and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"sum":"The Court held that the Social Security Administration's interpretations of the statute fell within its lawful interpretative authority.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"op":1,"sum":"The Court held that the specific intent to injure or defraud someone, whether the United States or another, is not an element of the misapplication of funds proscribed by section 1097(a).","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"California v. FERC","cite":"495 U.S. 490","y":1990,"id":"1989/89-333","sc":1,"sum":"The California requirements for minimum stream flows cannot be given effect and allowed to supplement the federal flow requirements.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Catskill Mountains Chapter of Trout Unlimited, Inc. v. New York","cite":"273 F.3d 481","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/273/481/","by":{"0":"24"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"0":"13, 21"}},{"t":"case","label":"EPA v. California ex rel. State Water Res. Control Bd.","cite":"426 U.S. 200","y":1976,"id":"1975/74-1435","sc":1,"sum":"While federal installations discharging water pollutants are obliged, under § 313 of the Federal Water Pollution Control Act Amendments of 1972 (Amendments), to comply to the same extent as nonfederal facilities with state \"requirements respecting control and abatement of pollution,\" obtaining a permit from a State with a federally approved permit program is not among such requirements. Federal installations are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4, 5, 19"}},{"t":"case","label":"Escondido Mut. Water Co. v. La Jolla Band of Mission Indians","cite":"466 U.S. 765","y":1984,"id":"1983/82-2056","sc":1,"sum":"Section 4(e) of the Federal Power Act (FPA) authorizes the Federal Energy Regulatory Commission (Commission) to issue licenses for the construction, operation, and maintenance of hydroelectric project works located on the public lands and reservations of the United States, including lands held in trust for Indians. The section contains a proviso that such licenses shall be issued \"within any reservation\" only after …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 47","y":1994,"url":"https://supreme.justia.com/cases/federal/us/510/47/","sc":1,"op":1,"by":{"0":"13, 18"}},{"t":"case","label":"First Iowa Hydro-Elec. Coop. v. FPC","cite":"328 U.S. 152","y":1946,"id":"scdb/1945-086","sc":1,"sum":"Petitioner applied to the Federal Power Commission for a license for a power project in Iowa involving the construction of a dam on a navigable stream and the diversion of water from two navigable streams into another. Section 9 (b) of the Federal Power Act requires an applicant to submit satisfactory evidence of compliance with requirements of state laws \"with respect to bed and banks and to the appropriation, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Helvering v. Morgan’s Inc.","cite":"293 U.S. 121","y":1934,"id":"scdb/1934-001","sc":1,"by":{"0":"13"}},{"t":"case","label":"National Wildlife Fed’n v. Consumers Power Co.","cite":"862 F.2d 580","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/862/580/","by":{"0":"16, 17"}},{"t":"case","label":"National Wildlife Fed’n v. Gorsuch","cite":"693 F.2d 156","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/693/156/","by":{"0":"17, 24, 26"}},{"t":"case","label":"North Carolina v. FERC","cite":"112 F.3d 1175","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/112/1175/","sum":"Holding that a withdrawal “resulting in a decrease in the volume of a preexisting discharge is not an activity that ‘results in any discharge’”.","sumSrc":"brief:0","by":{"0":"18, 22"}},{"t":"case","label":"Phelps Dodge Corp. v. NLRB","cite":"313 U.S. 177","y":1941,"id":"scdb/1940-080","sc":1,"by":{"0":"21"}},{"t":"case","label":"PUD No. 1 v. Washington Dep’t of Ecology","cite":"511 U.S. 700","y":1994,"id":"1993/92-1911","sc":1,"op":3,"ar":59,"sum":"Washington's minimum stream flow requirement is a permissible condition of a § 401 certification. Pp. 710-723. Cite as: 511 U. S. 700 (1994) (a) A State may impose conditions on certifications insofar as necessary to enforce a designated use contained in the State's water quality standard. Petitioners' claim that the State may only impose water quality limitations specifically tied to a \"discharge\" is contradicted …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 11, 14, 21, 23"}},{"t":"case","label":"Solid Waste Agency v. United States Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"South Fla.Water Mgmt. Dist. v. Miccosukee Tribe of Indians","cite":"541 U.S. 95","y":2004,"id":"2003/02-626","sc":1,"op":3,"sum":"The Court sent the case back to the district court to consider whether the water conservation area and the canal used to transport the water are distinct. If the district court decides the two are not distinct, then the water district will not need a permit under the Clean Water Act.","sumSrc":"Oyez","by":{"0":"11, 23, 24"}},{"t":"case","label":"United States v. Arizona","cite":"295 U.S. 174","y":1935,"id":"scdb/1934-055","sc":1,"op":1,"sum":"that executive action under the National Industrial Recovery Act relied on by the Government in this case to sustain the right to construct the dam in question, was not approval by direct order of the President.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"United States v. James","cite":"478 U.S. 597","y":1986,"id":"1985/85-434","sc":1,"sum":"Section 702c bars recovery against the Government in these cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Wyoming v. Colorado","cite":"259 U.S. 419","y":1922,"id":"scdb/1921-171","sc":1,"sum":"1. The waters of an innavigable stream rising in one State and flowing into a State adjoining may not be disposed of by the upper State as she may choose, regardless of the harm that may ensue to the lower State and her citizens.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"14"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","subs":["(a)","(a)(1)","(b)","(d)"],"stext":{"head":"§1251. Congressional declaration of goals and policy","paras":[[0,"(a) Restoration and maintenance of chemical, physical and biological integrity of Nation's waters; national goals for achievement of objective"],[0,"The objective of this chapter is to restore and maintain the chemical, physical, and biological integrity of the Nation's waters. In order to achieve this objective it is hereby declared that, consistent with the provisions of this chapter—"],[1,"(1) it is the national goal that the discharge of pollutants into the navigable waters be eliminated by 1985;"],[1,"(2) it is the national goal that wherever attainable, an interim goal of water quality which provides for the protection and propagation of fish, shellfish, and wildlife and provides for recreation in and on the water be achieved by July 1, 1983;"],[1,"(3) it is the national policy that the discharge of toxic pollutants in toxic amounts be prohibited;"],[1,"(4) it is the national policy that Federal financial assistance be provided to construct publicly owned waste treatment works;"],[1,"(5) it is the national policy that areawide waste treatment management planning processes be developed and implemented to assure adequate control of sources of pollutants in each State;"],[1,"(6) it is the national policy that a major research and demonstration effort be made to develop technology necessary to eliminate the discharge of pollutants into the navigable waters, waters of the contiguous zone, and the oceans; and"],[1,"(7) it is the national policy that programs for the control of nonpoint sources of pollution be developed and implemented in an expeditious manner so as to enable the goals of this chapter to be met through the control of both point and nonpoint sources of pollution."],[0,"(b) Congressional recognition, preservation, and protection of primary responsibilities and rights of States"],[0,"It is the policy of the Congress to recognize, preserve, and protect the primary responsibilities and rights of States to prevent, reduce, and eliminate pollution, to plan the development and use (including restoration, preservation, and enhancement) of land and water resources, and to consult with the Administrator in the exercise of his authority under this chapter. It is the policy of Congress that the States manage the construction grant program under this chapter and implement the permit programs under sections 1342 and 1344 of this title. It is further the policy of the Congress to support and aid research relating to the prevention, reduction, and elimination of pollution and to provide Federal technical services and financial aid to State and interstate agencies and municipalities in connection with the prevention, reduction, and elimination of pollution."],[0,"(c) Congressional policy toward Presidential activities with foreign countries"],[0,"It is further the policy of Congress that the President, acting through the Secretary of State and such national and international organizations as he determines appropriate, shall take such action as may be necessary to insure that to the fullest extent possible all foreign countries shall take meaningful action for the prevention, reduction, and elimination of pollution in their waters and in international waters and for the achievement of goals regarding the elimination of discharge of pollutants and the improvement of water quality to at least the same extent as the United States does under its laws."],[0,"(d) Administrator of Environmental Protection Agency to administer chapter"],[0,"Except as otherwise expressly provided in this chapter, the Administrator of the Environmental Protection Agency (hereinafter in this chapter called \"Administrator\") shall administer this chapter."],[0,"(e) Public participation in development, revision, and enforcement of any regulation, etc."],[0,"Public participation in the development, revision, and enforcement of any regulation, standard, effluent limitation, plan, or program established by the Administrator or any State under this chapter shall be provided for, encouraged, and assisted by the Administrator and the States. The Administrator, in cooperation with the States, shall develop and publish regulations specifying minimum guidelines for public participation in such processes."],[0,"(f) Procedures utilized for implementing chapter"],[0,"It is the national policy that to the maximum extent possible the procedures utilized for implementing this chapter shall encourage the drastic minimization of paperwork and interagency decision procedures, and the best use of available manpower and funds, so as to prevent needless duplication and unnecessary delays at all levels of government."],[0,"(g) Authority of States over water"],[0,"It is the policy of Congress that the authority of each State to allocate quantities of water within its jurisdiction shall not be superseded, abrogated or otherwise impaired by this chapter. It is the further policy of Congress that nothing in this chapter shall be construed to supersede or abrogate rights to quantities of water which have been established by any State. Federal agencies shall co-operate with State and local agencies to develop comprehensive solutions to prevent, reduce and eliminate pollution in concert with programs for managing water resources."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1251?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1251. Congressional declaration of goals and policy","tname":"Navigation and Navigable Waters","by":{"0":"passim, 4, 25, 4, 25, 2, 2"}},{"t":"usc","label":"33 U.S.C. § 1256","url":"https://www.law.cornell.edu/uscode/text/33/1256","by":{"0":"5"}},{"t":"usc","label":"33 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/33/1311","subs":["(a)","(a)(2)"],"stext":{"head":"§1311. Effluent limitations","paras":[[0,"(a) Illegality of pollutant discharges except in compliance with law"],[0,"Except as in compliance with this section and sections 1312, 1316, 1317, 1328, 1342, and 1344 of this title, the discharge of any pollutant by any person shall be unlawful."],[0,"(b) Timetable for achievement of objectives"],[0,"In order to carry out the objective of this chapter there shall be achieved—"],[1,"(1)(A) not later than July 1, 1977, effluent limitations for point sources, other than publicly owned treatment works, (i) which shall require the application of the best practicable control technology currently available as defined by the Administrator pursuant to section 1314(b) of this title, or (ii) in the case of a discharge into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, which shall require compliance with any applicable pretreatment requirements and any requirements under section 1317 of this title; and"],[1,"(B) for publicly owned treatment works in existence on July 1, 1977, or approved pursuant to section 1283 of this title prior to June 30, 1974 (for which construction must be completed within four years of approval), effluent limitations based upon secondary treatment as defined by the Administrator pursuant to section 1314(d)(1) of this title; or,"],[1,"(C) not later than July 1, 1977, any more stringent limitation, including those necessary to meet water quality standards, treatment standards, or schedules of compliance, established pursuant to any State law or regulations (under authority preserved by section 1370 of this title) or any other Federal law or regulation, or required to implement any applicable water quality standard established pursuant to this chapter."],[1,"(2)(A) for pollutants identified in subparagraphs (C), (D), and (F) of this paragraph, effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which (i) shall require application of the best available technology economically achievable for such category or class, which will result in reasonable further progress toward the national goal of eliminating the discharge of all pollutants, as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, which such effluent limitations shall require the elimination of discharges of all pollutants if the Administrator finds, on the basis of information available to him (including information developed pursuant to section 1325 of this title), that such elimination is technologically and economically achievable for a category or class of point sources as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, or (ii) in the case of the introduction of a pollutant into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, shall require compliance with any applicable pretreatment requirements and any other requirement under section 1317 of this title;"],[1,"(B) Repealed. Pub. L. 97–117, §21(b), Dec. 29, 1981, 95 Stat. 1632."],[1,"(C) with respect to all toxic pollutants referred to in table 1 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(D) for all toxic pollutants listed under paragraph (1) of subsection (a) of section 1317 of this title which are not referred to in subparagraph (C) of this paragraph compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable, but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(E) as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989, compliance with effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which in the case of pollutants identified pursuant to section 1314(a)(4) of this title shall require application of the best conventional pollutant control technology as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(4) of this title; and"],[1,"(F) for all pollutants (other than those subject to subparagraphs (C), (D), or (E) of this paragraph) compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than 3 years after the date such limitations are established, and in no case later than March 31, 1989."],[1,"(3)(A) for effluent limitations under paragraph (1)(A)(i) of this subsection promulgated after January 1, 1982, and requiring a level of control substantially greater or based on fundamentally different control technology than under permits for an industrial category issued before such date, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989; and"],[1,"(B) for any effluent limitation in accordance with paragraph (1)(A)(i), (2)(A)(i), or (2)(E) of this subsection established only on the basis of section 1342(a)(1) of this title in a permit issued after February 4, 1987, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are established, and in no case later than March 31, 1989."],[0,"(c) Modification of timetable"],[0,"The Administrator may modify the requirements of subsection (b)(2)(A) of this section with respect to any point source for which a permit application is filed after July 1, 1977, upon a showing by the owner or operator of such point source satisfactory to the Administrator that such modified requirements (1) will represent the maximum use of technology within the economic capability of the owner or operator; and (2) will result in reasonable further progress toward the elimination of the discharge of pollutants."],[0,"(d) Review and revision of effluent limitations"],[0,"Any effluent limitation required by paragraph (2) of subsection (b) of this section shall be reviewed at least every five years and, if appropriate, revised pursuant to the procedure established under such paragraph."],[0,"(e) All point discharge source application of effluent limitations"],[0,"Effluent limitations established pursuant to this section or section 1312 of this title shall be applied to all point sources of discharge of pollutants in accordance with the provisions of this chapter."],[0,"(f) Illegality of discharge of radiological, chemical, or biological warfare agents, high-level radioactive waste, or medical waste"],[0,"Notwithstanding any other provisions of this chapter it shall be unlawful to discharge any radiological, chemical, or biological warfare agent, any high-level radioactive waste, or any medical waste, into the navigable waters."],[0,"(g) Modifications for certain nonconventional pollutants"],[0,"(1) General authority"],[1,"The Administrator, with the concurrence of the State, may modify the requirements of subsection (b)(2)(A) of this section with respect to the discharge from any point source of ammonia, chlorine, color, iron, and total phenols (4AAP) (when determined by the Administrator to be a pollutant covered by subsection (b)(2)(F)) and any other pollutant which the Administrator lists under paragraph (4) of this subsection."],[0,"(2) Requirements for granting modifications"],[1,"A modification under this subsection shall be granted only upon a showing by the owner or operator of a point source satisfactory to the Administrator that—"],[2,"(A) such modified requirements will result at a minimum in compliance with the requirements of subsection (b)(1)(A) or (C) of this section, whichever is applicable;"],[2,"(B) such modified requirements will not result in any additional requirements on any other point or nonpoint source; and"],[2,"(C) such modification will not interfere with the attainment or maintenance of that water quality which shall assure protection of public water supplies, and the protection and propagation of a balanced population of shellfish, fish, and wildlife, and allow recreational activities, in and on the water and such modification will not result in the discharge of pollutants in quantities which may reasonably be anticipated to pose an unacceptable risk to human health or the environment because of bioaccumulation, persistency in the environment, acute toxicity, chronic toxicity (including carcinogenicity, mutagenicity or teratogenicity), or synergistic propensities."],[0,"(3) Limitation on authority to apply for subsection (c) modification"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1311?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1311. Effluent limitations","tname":"Navigation and Navigable Waters","by":{"0":"6, 19, 20, 4, 19, 19, 4"}},{"t":"usc","label":"33 U.S.C. § 1312","url":"https://www.law.cornell.edu/uscode/text/33/1312","subs":["(a)(9)"],"by":{"0":"6, 19"}},{"t":"usc","label":"33 U.S.C. § 1313","url":"https://www.law.cornell.edu/uscode/text/33/1313","subs":["(c)(2)(A)"],"stext":{"head":"§1313. Water quality standards and implementation plans","paras":[[0,"(a) Existing water quality standards"],[0,"(1) In order to carry out the purpose of this chapter, any water quality standard applicable to interstate waters which was adopted by any State and submitted to, and approved by, or is awaiting approval by, the Administrator pursuant to this Act as in effect immediately prior to October 18, 1972, shall remain in effect unless the Administrator determined that such standard is not consistent with the applicable requirements of this Act as in effect immediately prior to October 18, 1972. If the Administrator makes such a determination he shall, within three months after October 18, 1972, notify the State and specify the changes needed to meet such requirements. If such changes are not adopted by the State within ninety days after the date of such notification, the Administrator shall promulgate such changes in accordance with subsection (b) of this section."],[0,"(2) Any State which, before October 18, 1972, has adopted, pursuant to its own law, water quality standards applicable to intrastate waters shall submit such standards to the Administrator within thirty days after October 18, 1972. Each such standard shall remain in effect, in the same manner and to the same extent as any other water quality standard established under this chapter unless the Administrator determines that such standard is inconsistent with the applicable requirements of this Act as in effect immediately prior to October 18, 1972. If the Administrator makes such a determination he shall not later than the one hundred and twentieth day after the date of submission of such standards, notify the State and specify the changes needed to meet such requirements. If such changes are not adopted by the State within ninety days after such notification, the Administrator shall promulgate such changes in accordance with subsection (b) of this section."],[0,"(3)(A) Any State which prior to October 18, 1972, has not adopted pursuant to its own laws water quality standards applicable to intrastate waters shall, not later than one hundred and eighty days after October 18, 1972, adopt and submit such standards to the Administrator."],[0,"(B) If the Administrator determines that any such standards are consistent with the applicable requirements of this Act as in effect immediately prior to October 18, 1972, he shall approve such standards."],[0,"(C) If the Administrator determines that any such standards are not consistent with the applicable requirements of this Act as in effect immediately prior to October 18, 1972, he shall, not later than the ninetieth day after the date of submission of such standards, notify the State and specify the changes to meet such requirements. If such changes are not adopted by the State within ninety days after the date of notification, the Administrator shall promulgate such standards pursuant to subsection (b) of this section."],[0,"(b) Proposed regulations"],[0,"(1) The Administrator shall promptly prepare and publish proposed regulations setting forth water quality standards for a State in accordance with the applicable requirements of this Act as in effect immediately prior to October 18, 1972, if—"],[1,"(A) the State fails to submit water quality standards within the times prescribed in subsection (a) of this section."],[1,"(B) a water quality standard submitted by such State under subsection (a) of this section is determined by the Administrator not to be consistent with the applicable requirements of subsection (a) of this section."],[0,"(2) The Administrator shall promulgate any water quality standard published in a proposed regulation not later than one hundred and ninety days after the date he publishes any such proposed standard, unless prior to such promulgation, such State has adopted a water quality standard which the Administrator determines to be in accordance with subsection (a) of this section."],[0,"(c) Review; revised standards; publication"],[0,"(1) The Governor of a State or the State water pollution control agency of such State shall from time to time (but at least once each three year period beginning with October 18, 1972) hold public hearings for the purpose of reviewing applicable water quality standards and, as appropriate, modifying and adopting standards. Results of such review shall be made available to the Administrator."],[0,"(2)(A) Whenever the State revises or adopts a new standard, such revised or new standard shall be submitted to the Administrator. Such revised or new water quality standard shall consist of the designated uses of the navigable waters involved and the water quality criteria for such waters based upon such uses. Such standards shall be such as to protect the public health or welfare, enhance the quality of water and serve the purposes of this chapter. Such standards shall be established taking into consideration their use and value for public water supplies, propagation of fish and wildlife, recreational purposes, and agricultural, industrial, and other purposes, and also taking into consideration their use and value for navigation."],[0,"(B) Whenever a State reviews water quality standards pursuant to paragraph (1) of this subsection, or revises or adopts new standards pursuant to this paragraph, such State shall adopt criteria for all toxic pollutants listed pursuant to section 1317(a)(1) of this title for which criteria have been published under section 1314(a) of this title, the discharge or presence of which in the affected waters could reasonably be expected to interfere with those designated uses adopted by the State, as necessary to support such designated uses. Such criteria shall be specific numerical criteria for such toxic pollutants. Where such numerical criteria are not available, whenever a State reviews water quality standards pursuant to paragraph (1), or revises or adopts new standards pursuant to this paragraph, such State shall adopt criteria based on biological monitoring or assessment methods consistent with information published pursuant to section 1314(a)(8) of this title. Nothing in this section shall be construed to limit or delay the use of effluent limitations or other permit conditions based on or involving biological monitoring or assessment methods or previously adopted numerical criteria."],[0,"(3) If the Administrator, within sixty days after the date of submission of the revised or new standard, determines that such standard meets the requirements of this chapter, such standard shall thereafter be the water quality standard for the applicable waters of that State. If the Administrator determines that any such revised or new standard is not consistent with the applicable requirements of this chapter, he shall not later than the ninetieth day after the date of submission of such standard notify the State and specify the changes to meet such requirements. If such changes are not adopted by the State within ninety days after the date of notification, the Administrator shall promulgate such standard pursuant to paragraph (4) of this subsection."],[0,"(4) The Administrator shall promptly prepare and publish proposed regulations setting forth a revised or new water quality standard for the navigable waters involved—"],[1,"(A) if a revised or new water quality standard submitted by such State under paragraph (3) of this subsection for such waters is determined by the Administrator not to be consistent with the applicable requirements of this chapter, or"],[1,"(B) in any case where the Administrator determines that a revised or new standard is necessary to meet the requirements of this chapter."],[0,"The Administrator shall promulgate any revised or new standard under this paragraph not later than ninety days after he publishes such proposed standards, unless prior to such promulgation, such State has adopted a revised or new water quality standard which the Administrator determines to be in accordance with this chapter."],[0,"(d) Identification of areas with insufficient controls; maximum daily load; certain effluent limitations revision"],[0,"(1)(A) Each State shall identify those waters within its boundaries for which the effluent limitations required by section 1311(b)(1)(A) and section 1311(b)(1)(B) of this title are not stringent enough to implement any water quality standard applicable to such waters. The State shall establish a priority ranking for such waters, taking into account the severity of the pollution and the uses to be made of such waters."],[0,"(B) Each State shall identify those waters or parts thereof within its boundaries for which controls on thermal discharges under section 1311 of this title are not stringent enough to assure protection and propagation of a balanced indigenous population of shellfish, fish, and wildlife."],[0,"(C) Each State shall establish for the waters identified in paragraph (1)(A) of this subsection, and in accordance with the priority ranking, the total maximum daily load, for those pollutants which the Administrator identifies under section 1314(a)(2) of this title as suitable for such calculation. Such load shall be established at a level necessary to implement the applicable water quality standards with seasonal variations and a margin of safety which takes into account any lack of knowledge concerning the relationship between effluent limitations and water quality."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1313?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1313. Water quality standards and implementation plans","tname":"Navigation and Navigable Waters","by":{"0":"6, 27, 6"}},{"t":"usc","label":"33 U.S.C. § 1314","url":"https://www.law.cornell.edu/uscode/text/33/1314","subs":["(f)(2)(C)","(f)(2)(F)"],"by":{"0":"5, 27, 27"}},{"t":"usc","label":"33 U.S.C. § 1316","url":"https://www.law.cornell.edu/uscode/text/33/1316","stext":{"head":"§1316. National standards of performance","paras":[[0,"(a) Definitions"],[0,"For purposes of this section:"],[0,"(1) The term \"standard of performance\" means a standard for the control of the discharge of pollutants which reflects the greatest degree of effluent reduction which the Administrator determines to be achievable through application of the best available demonstrated control technology, processes, operating methods, or other alternatives, including, where practicable, a standard permitting no discharge of pollutants."],[0,"(2) The term \"new source\" means any source, the construction of which is commenced after the publication of proposed regulations prescribing a standard of performance under this section which will be applicable to such source, if such standard is thereafter promulgated in accordance with this section."],[0,"(3) The term \"source\" means any building, structure, facility, or installation from which there is or may be the discharge of pollutants."],[0,"(4) The term \"owner or operator\" means any person who owns, leases, operates, controls, or supervises a source."],[0,"(5) The term \"construction\" means any placement, assembly, or installation of facilities or equipment (including contractual obligations to purchase such facilities or equipment) at the premises where such equipment will be used, including preparation work at such premises."],[0,"(b) Categories of sources; Federal standards of performance for new sources"],[0,"(1)(A) The Administrator shall, within ninety days after October 18, 1972, publish (and from time to time thereafter shall revise) a list of categories of sources, which shall, at the minimum, include:"],[1,"pulp and paper mills;"],[1,"paperboard, builders paper and board mills;"],[1,"meat product and rendering processing;"],[1,"dairy product processing;"],[1,"grain mills;"],[1,"canned and preserved fruits and vegetables processing;"],[1,"canned and preserved seafood processing;"],[1,"sugar processing;"],[1,"textile mills;"],[1,"cement manufacturing;"],[1,"feedlots;"],[1,"electroplating;"],[1,"organic chemicals manufacturing;"],[1,"inorganic chemicals manufacturing;"],[1,"plastic and synthetic materials manufacturing;"],[1,"soap and detergent manufacturing;"],[1,"fertilizer manufacturing;"],[1,"petroleum refining;"],[1,"iron and steel manufacturing;"],[1,"nonferrous metals manufacturing;"],[1,"phosphate manufacturing;"],[1,"steam electric powerplants;"],[1,"ferroalloy manufacturing;"],[1,"leather tanning and finishing;"],[1,"glass and asbestos manufacturing;"],[1,"rubber processing; and"],[1,"timber products processing."],[0,"(B) As soon as practicable, but in no case more than one year, after a category of sources is included in a list under subparagraph (A) of this paragraph, the Administrator shall propose and publish regulations establishing Federal standards of performance for new sources within such category. The Administrator shall afford interested persons an opportunity for written comment on such proposed regulations. After considering such comments, he shall promulgate, within one hundred and twenty days after publication of such proposed regulations, such standards with such adjustments as he deems appropriate. The Administrator shall, from time to time, as technology and alternatives change, revise such standards following the procedure required by this subsection for promulgation of such standards. Standards of performance, or revisions thereof, shall become effective upon promulgation. In establishing or revising Federal standards of performance for new sources under this section, the Administrator shall take into consideration the cost of achieving such effluent reduction, and any non-water quality, environmental impact and energy requirements."],[0,"(2) The Administrator may distinguish among classes, types, and sizes within categories of new sources for the purpose of establishing such standards and shall consider the type of process employed (including whether batch or continuous)."],[0,"(3) The provisions of this section shall apply to any new source owned or operated by the United States."],[0,"(c) State enforcement of standards of performance"],[0,"Each State may develop and submit to the Administrator a procedure under State law for applying and enforcing standards of performance for new sources located in such State. If the Administrator finds that the procedure and the law of any State require the application and enforcement of standards of performance to at least the same extent as required by this section, such State is authorized to apply and enforce such standards of performance (except with respect to new sources owned or operated by the United States)."],[0,"(d) Protection from more stringent standards"],[0,"Notwithstanding any other provision of this chapter, any point source the construction of which is commenced after October 18, 1972, and which is so constructed as to meet all applicable standards of performance shall not be subject to any more stringent standard of performance during a ten-year period beginning on the date of completion of such construction or during the period of depreciation or amortization of such facility for the purposes of section 167 or 169 (or both) of title 26 whichever period ends first."],[0,"(e) Illegality of operation of new sources in violation of applicable standards of performance"],[0,"After the effective date of standards of performance promulgated under this section, it shall be unlawful for any owner or operator of any new source to operate such source in violation of any standard of performance applicable to such source."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1316?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1316. National standards of performance","tname":"Navigation and Navigable Waters","by":{"0":"6, 4"}},{"t":"usc","label":"33 U.S.C. § 1317","url":"https://www.law.cornell.edu/uscode/text/33/1317","stext":{"head":"§1317. Toxic and pretreatment effluent standards","paras":[[0,"(a) Toxic pollutant list; revision; hearing; promulgation of standards; effective date; consultation"],[0,"(1) On and after December 27, 1977, the list of toxic pollutants or combination of pollutants subject to this chapter shall consist of those toxic pollutants listed in table 1 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives, and the Administrator shall publish, not later than the thirtieth day after December 27, 1977, that list. From time to time thereafter, the Administrator may revise such list and the Administrator is authorized to add to or remove from such list any pollutant. The Administrator in publishing any revised list, including the addition or removal of any pollutant from such list, shall take into account toxicity of the pollutant, its persistence, degradability, the usual or potential presence of the affected organisms in any waters, the importance of the affected organisms, and the nature and extent of the effect of the toxic pollutant on such organisms. A determination of the Administrator under this paragraph shall be final except that if, on judicial review, such determination was based on arbitrary and capricious action of the Administrator, the Administrator shall make a redetermination."],[0,"(2) Each toxic pollutant listed in accordance with paragraph (1) of this subsection shall be subject to effluent limitations resulting from the application of the best available technology economically achievable for the applicable category or class of point sources established in accordance with sections 1311(b)(2)(A) and 1314(b)(2) of this title. The Administrator, in his discretion, may publish in the Federal Register a proposed effluent standard (which may include a prohibition) establishing requirements for a toxic pollutant which, if an effluent limitation is applicable to a class or category of point sources, shall be applicable to such category or class only if such standard imposes more stringent requirements. Such published effluent standard (or prohibition) shall take into account the toxicity of the pollutant, its persistence, degradability, the usual or potential presence of the affected organisms in any waters, the importance of the affected organisms and the nature and extent of the effect of the toxic pollutant on such organisms, and the extent to which effective control is being or may be achieved under other regulatory authority. The Administrator shall allow a period of not less than sixty days following publication of any such proposed effluent standard (or prohibition) for written comment by interested persons on such proposed standard. In addition, if within thirty days of publication of any such proposed effluent standard (or prohibition) any interested person so requests, the Administrator shall hold a public hearing in connection therewith. Such a public hearing shall provide an opportunity for oral and written presentations, such cross-examination as the Administrator determines is appropriate on disputed issues of material fact, and the transcription of a verbatim record which shall be available to the public. After consideration of such comments and any information and material presented at any public hearing held on such proposed standard or prohibition, the Administrator shall promulgate such standard (or prohibition) with such modification as the Administrator finds are justified. Such promulgation by the Administrator shall be made within two hundred and seventy days after publication of proposed standard (or prohibition). Such standard (or prohibition) shall be final except that if, on judicial review, such standard was not based on substantial evidence, the Administrator shall promulgate a revised standard. Effluent limitations shall be established in accordance with sections 1311(b)(2)(A) and 1314(b)(2) of this title for every toxic pollutant referred to in table 1 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives as soon as practicable after December 27, 1977, but no later than July 1, 1980. Such effluent limitations or effluent standards (or prohibitions) shall be established for every other toxic pollutant listed under paragraph (1) of this subsection as soon as practicable after it is so listed."],[0,"(3) Each such effluent standard (or prohibition) shall be reviewed and, if appropriate, revised at least every three years."],[0,"(4) Any effluent standard promulgated under this section shall be at that level which the Administrator determines provides an ample margin of safety."],[0,"(5) When proposing or promulgating any effluent standard (or prohibition) under this section, the Administrator shall designate the category or categories of sources to which the effluent standard (or prohibition) shall apply. Any disposal of dredged material may be included in such a category of sources after consultation with the Secretary of the Army."],[0,"(6) Any effluent standard (or prohibition) established pursuant to this section shall take effect on such date or dates as specified in the order promulgating such standard, but in no case, more than one year from the date of such promulgation. If the Administrator determines that compliance within one year from the date of promulgation is technologically infeasible for a category of sources, the Administrator may establish the effective date of the effluent standard (or prohibition) for such category at the earliest date upon which compliance can be feasibly attained by sources within such category, but in no event more than three years after the date of such promulgation."],[0,"(7) Prior to publishing any regulations pursuant to this section the Administrator shall, to the maximum extent practicable within the time provided, consult with appropriate advisory committees, States, independent experts, and Federal departments and agencies."],[0,"(b) Pretreatment standards; hearing; promulgation; compliance period; revision; application to State and local laws"],[0,"(1) The Administrator shall, within one hundred and eighty days after October 18, 1972, and from time to time thereafter, publish proposed regulations establishing pretreatment standards for introduction of pollutants into treatment works (as defined in section 1292 of this title) which are publicly owned for those pollutants which are determined not to be susceptible to treatment by such treatment works or which would interfere with the operation of such treatment works. Not later than ninety days after such publication, and after opportunity for public hearing, the Administrator shall promulgate such pretreatment standards. Pretreatment standards under this subsection shall specify a time for compliance not to exceed three years from the date of promulgation and shall be established to prevent the discharge of any pollutant through treatment works (as defined in section 1292 of this title) which are publicly owned, which pollutant interferes with, passes through, or otherwise is incompatible with such works. If, in the case of any toxic pollutant under subsection (a) of this section introduced by a source into a publicly owned treatment works, the treatment by such works removes all or any part of such toxic pollutant and the discharge from such works does not violate that effluent limitation or standard which would be applicable to such toxic pollutant if it were discharged by such source other than through a publicly owned treatment works, and does not prevent sludge use or disposal by such works in accordance with section 1345 of this title, then the pretreatment requirements for the sources actually discharging such toxic pollutant into such publicly owned treatment works may be revised by the owner or operator of such works to reflect the removal of such toxic pollutant by such works."],[0,"(2) The Administrator shall, from time to time, as control technology, processes, operating methods, or other alternatives change, revise such standards following the procedure established by this subsection for promulgation of such standards."],[0,"(3) When proposing or promulgating any pretreatment standard under this section, the Administrator shall designate the category or categories of sources to which such standard shall apply."],[0,"(4) Nothing in this subsection shall affect any pretreatment requirement established by any State or local law not in conflict with any pretreatment standard established under this subsection."],[0,"(c) New sources of pollutants into publicly owned treatment works"],[0,"In order to insure that any source introducing pollutants into a publicly owned treatment works, which source would be a new source subject to section 1316 of this title if it were to discharge pollutants, will not cause a violation of the effluent limitations established for any such treatment works, the Administrator shall promulgate pretreatment standards for the category of such sources simultaneously with the promulgation of standards of performance under section 1316 of this title for the equivalent category of new sources. Such pretreatment standards shall prevent the discharge of any pollutant into such treatment works, which pollutant may interfere with, pass through, or otherwise be incompatible with such works."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1317?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1317. Toxic and pretreatment effluent standards","tname":"Navigation and Navigable Waters","by":{"0":"6"}},{"t":"usc","label":"33 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/33/1341","subs":["(a)","(a)(1)","(b)","(d)"],"stext":{"head":"§1341. Certification","paras":[[0,"(a) Compliance with applicable requirements; application; procedures; license suspension"],[0,"(1) Any applicant for a Federal license or permit to conduct any activity including, but not limited to, the construction or operation of facilities, which may result in any discharge into the navigable waters, shall provide the licensing or permitting agency a certification from the State in which the discharge originates or will originate, or, if appropriate, from the interstate water pollution control agency having jurisdiction over the navigable waters at the point where the discharge originates or will originate, that any such discharge will comply with the applicable provisions of sections 1311, 1312, 1313, 1316, and 1317 of this title. In the case of any such activity for which there is not an applicable effluent limitation or other limitation under sections 1311(b) and 1312 of this title, and there is not an applicable standard under sections 1316 and 1317 of this title, the State shall so certify, except that any such certification shall not be deemed to satisfy section 1371(c) of this title. Such State or interstate agency shall establish procedures for public notice in the case of all applications for certification by it and, to the extent it deems appropriate, procedures for public hearings in connection with specific applications. In any case where a State or interstate agency has no authority to give such a certification, such certification shall be from the Administrator. If the State, interstate agency, or Administrator, as the case may be, fails or refuses to act on a request for certification, within a reasonable period of time (which shall not exceed one year) after receipt of such request, the certification requirements of this subsection shall be waived with respect to such Federal application. No license or permit shall be granted until the certification required by this section has been obtained or has been waived as provided in the preceding sentence. No license or permit shall be granted if certification has been denied by the State, interstate agency, or the Administrator, as the case may be."],[0,"(2) Upon receipt of such application and certification the licensing or permitting agency shall immediately notify the Administrator of such application and certification. Whenever such a discharge may affect, as determined by the Administrator, the quality of the waters of any other State, the Administrator within thirty days of the date of notice of application for such Federal license or permit shall so notify such other State, the licensing or permitting agency, and the applicant. If, within sixty days after receipt of such notification, such other State determines that such discharge will affect the quality of its waters so as to violate any water quality requirements in such State, and within such sixty-day period notifies the Administrator and the licensing or permitting agency in writing of its objection to the issuance of such license or permit and requests a public hearing on such objection, the licensing or permitting agency shall hold such a hearing. The Administrator shall at such hearing submit his evaluation and recommendations with respect to any such objection to the licensing or permitting agency. Such agency, based upon the recommendations of such State, the Administrator, and upon any additional evidence, if any, presented to the agency at the hearing, shall condition such license or permit in such manner as may be necessary to insure compliance with applicable water quality requirements. If the imposition of conditions cannot insure such compliance such agency shall not issue such license or permit."],[0,"(3) The certification obtained pursuant to paragraph (1) of this subsection with respect to the construction of any facility shall fulfill the requirements of this subsection with respect to certification in connection with any other Federal license or permit required for the operation of such facility unless, after notice to the certifying State, agency, or Administrator, as the case may be, which shall be given by the Federal agency to whom application is made for such operating license or permit, the State, or if appropriate, the interstate agency or the Administrator, notifies such agency within sixty days after receipt of such notice that there is no longer reasonable assurance that there will be compliance with the applicable provisions of sections 1311, 1312, 1313, 1316, and 1317 of this title because of changes since the construction license or permit certification was issued in (A) the construction or operation of the facility, (B) the characteristics of the waters into which such discharge is made, (C) the water quality criteria applicable to such waters or (D) applicable effluent limitations or other requirements. This paragraph shall be inapplicable in any case where the applicant for such operating license or permit has failed to provide the certifying State, or, if appropriate, the interstate agency or the Administrator, with notice of any proposed changes in the construction or operation of the facility with respect to which a construction license or permit has been granted, which changes may result in violation of section 1311, 1312, 1313, 1316, or 1317 of this title."],[0,"(4) Prior to the initial operation of any federally licensed or permitted facility or activity which may result in any discharge into the navigable waters and with respect to which a certification has been obtained pursuant to paragraph (1) of this subsection, which facility or activity is not subject to a Federal operating license or permit, the licensee or permittee shall provide an opportunity for such certifying State, or, if appropriate, the interstate agency or the Administrator to review the manner in which the facility or activity shall be operated or conducted for the purposes of assuring that applicable effluent limitations or other limitations or other applicable water quality requirements will not be violated. Upon notification by the certifying State, or if appropriate, the interstate agency or the Administrator that the operation of any such federally licensed or permitted facility or activity will violate applicable effluent limitations or other limitations or other water quality requirements such Federal agency may, after public hearing, suspend such license or permit. If such license or permit is suspended, it shall remain suspended until notification is received from the certifying State, agency, or Administrator, as the case may be, that there is reasonable assurance that such facility or activity will not violate the applicable provisions of section 1311, 1312, 1313, 1316, or 1317 of this title."],[0,"(5) Any Federal license or permit with respect to which a certification has been obtained under paragraph (1) of this subsection may be suspended or revoked by the Federal agency issuing such license or permit upon the entering of a judgment under this chapter that such facility or activity has been operated in violation of the applicable provisions of section 1311, 1312, 1313, 1316, or 1317 of this title."],[0,"(6) Except with respect to a permit issued under section 1342 of this title, in any case where actual construction of a facility has been lawfully commenced prior to April 3, 1970, no certification shall be required under this subsection for a license or permit issued after April 3, 1970, to operate such facility, except that any such license or permit issued without certification shall terminate April 3, 1973, unless prior to such termination date the person having such license or permit submits to the Federal agency which issued such license or permit a certification and otherwise meets the requirements of this section."],[0,"(b) Compliance with other provisions of law setting applicable water quality requirements"],[0,"Nothing in this section shall be construed to limit the authority of any department or agency pursuant to any other provision of law to require compliance with any applicable water quality requirements. The Administrator shall, upon the request of any Federal department or agency, or State or interstate agency, or applicant, provide, for the purpose of this section, any relevant information on applicable effluent limitations, or other limitations, standards, regulations, or requirements, or water quality criteria, and shall, when requested by any such department or agency or State or interstate agency, or applicant, comment on any methods to comply with such limitations, standards, regulations, requirements, or criteria."],[0,"(c) Authority of Secretary of the Army to permit use of spoil disposal areas by Federal licensees or permittees"],[0,"In order to implement the provisions of this section, the Secretary of the Army, acting through the Chief of Engineers, is authorized, if he deems it to be in the public interest, to permit the use of spoil disposal areas under his jurisdiction by Federal licensees or permittees, and to make an appropriate charge for such use. Moneys received from such licensees or permittees shall be deposited in the Treasury as miscellaneous receipts."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1341?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1341. Certification","tname":"Navigation and Navigable Waters","by":{"0":"passim, passim, 2, 2, 4, 5, 19, 20, 24, 25"}},{"t":"usc","label":"33 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/33/1342","subs":["(a)","(b)"],"stext":{"head":"§1342. National pollutant discharge elimination system","paras":[[0,"(a) Permits for discharge of pollutants"],[0,"(1) Except as provided in sections 1328 and 1344 of this title, the Administrator may, after opportunity for public hearing issue a permit for the discharge of any pollutant, or combination of pollutants, notwithstanding section 1311(a) of this title, upon condition that such discharge will meet either (A) all applicable requirements under sections 1311, 1312, 1316, 1317, 1318, and 1343 of this title, or (B) prior to the taking of necessary implementing actions relating to all such requirements, such conditions as the Administrator determines are necessary to carry out the provisions of this chapter."],[0,"(2) The Administrator shall prescribe conditions for such permits to assure compliance with the requirements of paragraph (1) of this subsection, including conditions on data and information collection, reporting, and such other requirements as he deems appropriate."],[0,"(3) The permit program of the Administrator under paragraph (1) of this subsection, and permits issued thereunder, shall be subject to the same terms, conditions, and requirements as apply to a State permit program and permits issued thereunder under subsection (b) of this section."],[0,"(4) All permits for discharges into the navigable waters issued pursuant to section 407 of this title shall be deemed to be permits issued under this subchapter, and permits issued under this subchapter shall be deemed to be permits issued under section 407 of this title, and shall continue in force and effect for their term unless revoked, modified, or suspended in accordance with the provisions of this chapter."],[0,"(5) No permit for a discharge into the navigable waters shall be issued under section 407 of this title after October 18, 1972. Each application for a permit under section 407 of this title, pending on October 18, 1972, shall be deemed to be an application for a permit under this section. The Administrator shall authorize a State, which he determines has the capability of administering a permit program which will carry out the objectives of this chapter to issue permits for discharges into the navigable waters within the jurisdiction of such State. The Administrator may exercise the authority granted him by the preceding sentence only during the period which begins on October 18, 1972, and ends either on the ninetieth day after the date of the first promulgation of guidelines required by section 1314(i)(2) of this title, or the date of approval by the Administrator of a permit program for such State under subsection (b) of this section, whichever date first occurs, and no such authorization to a State shall extend beyond the last day of such period. Each such permit shall be subject to such conditions as the Administrator determines are necessary to carry out the provisions of this chapter. No such permit shall issue if the Administrator objects to such issuance."],[0,"(b) State permit programs"],[0,"At any time after the promulgation of the guidelines required by subsection (i)(2) of section 1314 of this title, the Governor of each State desiring to administer its own permit program for discharges into navigable waters within its jurisdiction may submit to the Administrator a full and complete description of the program it proposes to establish and administer under State law or under an interstate compact. In addition, such State shall submit a statement from the attorney general (or the attorney for those State water pollution control agencies which have independent legal counsel), or from the chief legal officer in the case of an interstate agency, that the laws of such State, or the interstate compact, as the case may be, provide adequate authority to carry out the described program. The Administrator shall approve each submitted program unless he determines that adequate authority does not exist:"],[0,"(1) To issue permits which—"],[1,"(A) apply, and insure compliance with, any applicable requirements of sections 1311, 1312, 1316, 1317, and 1343 of this title;"],[1,"(B) are for fixed terms not exceeding five years; and"],[1,"(C) can be terminated or modified for cause including, but not limited to, the following:"],[2,"(i) violation of any condition of the permit;"],[2,"(ii) obtaining a permit by misrepresentation, or failure to disclose fully all relevant facts;"],[2,"(iii) change in any condition that requires either a temporary or permanent reduction or elimination of the permitted discharge;"],[1,"(D) control the disposal of pollutants into wells;"],[0,"(2)(A) To issue permits which apply, and insure compliance with, all applicable requirements of section 1318 of this title; or"],[0,"(B) To inspect, monitor, enter, and require reports to at least the same extent as required in section 1318 of this title;"],[0,"(3) To insure that the public, and any other State the waters of which may be affected, receive notice of each application for a permit and to provide an opportunity for public hearing before a ruling on each such application;"],[0,"(4) To insure that the Administrator receives notice of each application (including a copy thereof) for a permit;"],[0,"(5) To insure that any State (other than the permitting State), whose waters may be affected by the issuance of a permit may submit written recommendations to the permitting State (and the Administrator) with respect to any permit application and, if any part of such written recommendations are not accepted by the permitting State, that the permitting State will notify such affected State (and the Administrator) in writing of its failure to so accept such recommendations together with its reasons for so doing;"],[0,"(6) To insure that no permit will be issued if, in the judgment of the Secretary of the Army acting through the Chief of Engineers, after consultation with the Secretary of the department in which the Coast Guard is operating, anchorage and navigation of any of the navigable waters would be substantially impaired thereby;"],[0,"(7) To abate violations of the permit or the permit program, including civil and criminal penalties and other ways and means of enforcement;"],[0,"(8) To insure that any permit for a discharge from a publicly owned treatment works includes conditions to require the identification in terms of character and volume of pollutants of any significant source introducing pollutants subject to pretreatment standards under section 1317(b) of this title into such works and a program to assure compliance with such pretreatment standards by each such source, in addition to adequate notice to the permitting agency of (A) new introductions into such works of pollutants from any source which would be a new source as defined in section 1316 of this title if such source were discharging pollutants, (B) new introductions of pollutants into such works from a source which would be subject to section 1311 of this title if it were discharging such pollutants, or (C) a substantial change in volume or character of pollutants being introduced into such works by a source introducing pollutants into such works at the time of issuance of the permit. Such notice shall include information on the quality and quantity of effluent to be introduced into such treatment works and any anticipated impact of such change in the quantity or quality of effluent to be discharged from such publicly owned treatment works; and"],[0,"(9) To insure that any industrial user of any publicly owned treatment works will comply with sections 1284(b), 1317, and 1318 of this title."],[0,"(c) Suspension of Federal program upon submission of State program; withdrawal of approval of State program; return of State program to Administrator"],[0,"(1) Not later than ninety days after the date on which a State has submitted a program (or revision thereof) pursuant to subsection (b) of this section, the Administrator shall suspend the issuance of permits under subsection (a) of this section as to those discharges subject to such program unless he determines that the State permit program does not meet the requirements of subsection (b) of this section or does not conform to the guidelines issued under section 1314(i)(2) of this title. If the Administrator so determines, he shall notify the State of any revisions or modifications necessary to conform to such requirements or guidelines."],[0,"(2) Any State permit program under this section shall at all times be in accordance with this section and guidelines promulgated pursuant to section 1314(i)(2) of this title."],[0,"(3) Whenever the Administrator determines after public hearing that a State is not administering a program approved under this section in accordance with requirements of this section, he shall so notify the State and, if appropriate corrective action is not taken within a reasonable time, not to exceed ninety days, the Administrator shall withdraw approval of such program. The Administrator shall not withdraw approval of any such program unless he shall first have notified the State, and made public, in writing, the reasons for such withdrawal."],[0,"(4) Limitations on partial permit program returns and withdrawals.—A State may return to the Administrator administration, and the Administrator may withdraw under paragraph (3) of this subsection approval, of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1342?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1342. National pollutant discharge elimination system","tname":"Navigation and Navigable Waters","by":{"0":"4, 5, 19, 20, 24, 25, 19, 24, 5"}},{"t":"usc","label":"33 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/33/1344","subs":["(a)","(g)"],"by":{"0":"4, 5, 1, 5"}},{"t":"usc","label":"33 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/33/1362","subs":["(6)","(7)","(12)","(14)","(16)","(19)"],"stext":{"head":"§1362. Definitions","paras":[[0,"Except as otherwise specifically provided, when used in this chapter:"],[0,"(1) The term \"State water pollution control agency\" means the State agency designated by the Governor having responsibility for enforcing State laws relating to the abatement of pollution."],[0,"(2) The term \"interstate agency\" means an agency of two or more States established by or pursuant to an agreement or compact approved by the Congress, or any other agency of two or more States, having substantial powers or duties pertaining to the control of pollution as determined and approved by the Administrator."],[0,"(3) The term \"State\" means a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Commonwealth of the Northern Mariana Islands, and the Trust Territory of the Pacific Islands."],[0,"(4) The term \"municipality\" means a city, town, borough, county, parish, district, association, or other public body created by or pursuant to State law and having jurisdiction over disposal of sewage, industrial wastes, or other wastes, or an Indian tribe or an authorized Indian tribal organization, or a designated and approved management agency under section 1288 of this title."],[0,"(5) The term \"person\" means an individual, corporation, partnership, association, State, municipality, commission, or political subdivision of a State, or any interstate body."],[0,"(6) The term \"pollutant\" means dredged spoil, solid waste, incinerator residue, sewage, garbage, sewage sludge, munitions, chemical wastes, biological materials, radioactive materials, heat, wrecked or discarded equipment, rock, sand, cellar dirt and industrial, municipal, and agricultural waste discharged into water. This term does not mean (A) \"sewage from vessels or a discharge incidental to the normal operation of a vessel of the Armed Forces\" within the meaning of section 1322 of this title; or (B) water, gas, or other material which is injected into a well to facilitate production of oil or gas, or water derived in association with oil or gas production and disposed of in a well, if the well used either to facilitate production or for disposal purposes is approved by authority of the State in which the well is located, and if such State determines that such injection or disposal will not result in the degradation of ground or surface water resources."],[0,"(7) The term \"navigable waters\" means the waters of the United States, including the territorial seas."],[0,"(8) The term \"territorial seas\" means the belt of the seas measured from the line of ordinary low water along that portion of the coast which is in direct contact with the open sea and the line marking the seaward limit of inland waters, and extending seaward a distance of three miles."],[0,"(9) The term \"contiguous zone\" means the entire zone established or to be established by the United States under article 24 of the Convention of the Territorial Sea and the Contiguous Zone."],[0,"(10) The term \"ocean\" means any portion of the high seas beyond the contiguous zone."],[0,"(11) The term \"effluent limitation\" means any restriction established by a State or the Administrator on quantities, rates, and concentrations of chemical, physical, biological, and other constituents which are discharged from point sources into navigable waters, the waters of the contiguous zone, or the ocean, including schedules of compliance."],[0,"(12) The term \"discharge of a pollutant\" and the term \"discharge of pollutants\" each means (A) any addition of any pollutant to navigable waters from any point source, (B) any addition of any pollutant to the waters of the contiguous zone or the ocean from any point source other than a vessel or other floating craft."],[0,"(13) The term \"toxic pollutant\" means those pollutants, or combinations of pollutants, including disease-causing agents, which after discharge and upon exposure, ingestion, inhalation or assimilation into any organism, either directly from the environment or indirectly by ingestion through food chains, will, on the basis of information available to the Administrator, cause death, disease, behavioral abnormalities, cancer, genetic mutations, physiological malfunctions (including malfunctions in reproduction) or physical deformations, in such organisms or their offspring."],[0,"(14) The term \"point source\" means any discernible, confined and discrete conveyance, including but not limited to any pipe, ditch, channel, tunnel, conduit, well, discrete fissure, container, rolling stock, concentrated animal feeding operation, or vessel or other floating craft, from which pollutants are or may be discharged. This term does not include agricultural stormwater discharges and return flows from irrigated agriculture."],[0,"(15) The term \"biological monitoring\" shall mean the determination of the effects on aquatic life, including accumulation of pollutants in tissue, in receiving waters due to the discharge of pollutants (A) by techniques and procedures, including sampling of organisms representative of appropriate levels of the food chain appropriate to the volume and the physical, chemical, and biological characteristics of the effluent, and (B) at appropriate frequencies and locations."],[0,"(16) The term \"discharge\" when used without qualification includes a discharge of a pollutant, and a discharge of pollutants."],[0,"(17) The term \"schedule of compliance\" means a schedule of remedial measures including an enforceable sequence of actions or operations leading to compliance with an effluent limitation, other limitation, prohibition, or standard."],[0,"(18) The term \"industrial user\" means those industries identified in the Standard Industrial Classification Manual, Bureau of the Budget, 1967, as amended and supplemented, under the category of \"Division D—Manufacturing\" and such other classes of significant waste producers as, by regulation, the Administrator deems appropriate."],[0,"(19) The term \"pollution\" means the man-made or man-induced alteration of the chemical, physical, biological, and radiological integrity of water."],[0,"(20) The term \"medical waste\" means isolation wastes; infectious agents; human blood and blood products; pathological wastes; sharps; body parts; contaminated bedding; surgical wastes and potentially contaminated laboratory wastes; dialysis wastes; and such additional medical items as the Administrator shall prescribe by regulation."],[0,"(21) Coastal recreation waters.—"],[1,"(A) In general.—The term \"coastal recreation waters\" means—"],[2,"(i) the Great Lakes; and"],[2,"(ii) marine coastal waters (including coastal estuaries) that are designated under section 1313(c) of this title by a State for use for swimming, bathing, surfing, or similar water contact activities."],[1,"(B) Exclusions.—The term \"coastal recreation waters\" does not include—"],[2,"(i) inland waters; or"],[2,"(ii) waters upstream of the mouth of a river or stream having an unimpaired natural connection with the open sea."],[0,"(22) Floatable material.—"],[1,"(A) In general.—The term \"floatable material\" means any foreign matter that may float or remain suspended in the water column."],[1,"(B) Inclusions.—The term \"floatable material\" includes—"],[2,"(i) plastic;"],[2,"(ii) aluminum cans;"],[2,"(iii) wood products;"],[2,"(iv) bottles; and"],[2,"(v) paper products."],[0,"(23) Pathogen indicator.—The term \"pathogen indicator\" means a substance that indicates the potential for human infectious disease."],[0,"(24) Oil and gas exploration and production.—The term \"oil and gas exploration, production, processing, or treatment operations or transmission facilities\" means all field activities or operations associated with exploration, production, processing, or treatment operations, or transmission facilities, including activities necessary to prepare a site for drilling and for the movement and placement of drilling equipment, whether or not such field activities or operations may be considered to be construction activities."],[0,"(25) Recreational vessel.—"],[1,"(A) In general.—The term \"recreational vessel\" means any vessel that is—"],[2,"(i) manufactured or used primarily for pleasure; or"],[2,"(ii) leased, rented, or chartered to a person for the pleasure of that person."],[1,"(B) Exclusion.—The term \"recreational vessel\" does not include a vessel that is subject to Coast Guard inspection and that—"],[2,"(i) is engaged in commercial use; or"],[2,"(ii) carries paying passengers."],[0,"(26) Treatment works.—The term \"treatment works\" has the meaning given the term in section 1292 of this title."],[0,"(27) Green infrastructure.—The term \"green infrastructure\" means the range of measures that use plant or soil systems, permeable pavement or other permeable surfaces or substrates, stormwater harvest and reuse, or landscaping to store, infiltrate, or evapotranspirate stormwater and reduce flows to sewer systems or to surface waters."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1362?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1362. Definitions","tname":"Navigation and Navigable Waters","by":{"0":"12, 12, 16, 21, 12, 16, 21, 12, 12, 27, 27"}},{"t":"usc","label":"33 U.S.C. § 1370","url":"https://www.law.cornell.edu/uscode/text/33/1370","stext":{"head":"§1370. State authority","paras":[[0,"Except as expressly provided in this chapter, nothing in this chapter shall (1) preclude or deny the right of any State or political subdivision thereof or interstate agency to adopt or enforce (A) any standard or limitation respecting discharges of pollutants, or (B) any requirement respecting control or abatement of pollution; except that if an effluent limitation, or other limitation, effluent standard, prohibition, pretreatment standard, or standard of performance is in effect under this chapter, such State or political subdivision or interstate agency may not adopt or enforce any effluent limitation, or other limitation, effluent standard, prohibition, pretreatment standard, or standard of performance which is less stringent than the effluent limitation, or other limitation, effluent standard, prohibition, pretreatment standard, or standard of performance under this chapter; or (2) be construed as impairing or in any manner affecting any right or jurisdiction of the States with respect to the waters (including boundary waters) of such States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1370?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1370. State authority","tname":"Navigation and Navigable Waters","by":{"0":"27"}},{"t":"usc","label":"33 U.S.C. § 1371","url":"https://www.law.cornell.edu/uscode/text/33/1371","subs":["(c)(2)"],"stext":{"head":"§1371. Authority under other laws and regulations","paras":[[0,"(a) Impairment of authority or functions of officials and agencies; treaty provisions"],[0,"This chapter shall not be construed as (1) limiting the authority or functions of any officer or agency of the United States under any other law or regulation not inconsistent with this chapter; (2) affecting or impairing the authority of the Secretary of the Army (A) to maintain navigation or (B) under the Act of March 3, 1899, (30 Stat. 1112); except that any permit issued under section 1344 of this title shall be conclusive as to the effect on water quality of any discharge resulting from any activity subject to section 403 of this title, or (3) affecting or impairing the provisions of any treaty of the United States."],[0,"(b) Discharges of pollutants into navigable waters"],[0,"Discharges of pollutants into the navigable waters subject to the Rivers and Harbors Act of 1910 (36 Stat. 593; 33 U.S.C. 421) and the Supervisory Harbors Act of 1888 (25 Stat. 209; 33 U.S.C. 441–451b) shall be regulated pursuant to this chapter, and not subject to such Act of 1910 and the Act of 1888 except as to effect on navigation and anchorage."],[0,"(c) Action of the Administrator deemed major Federal action; construction of the National Environmental Policy Act of 1969"],[0,"(1) Except for the provision of Federal financial assistance for the purpose of assisting the construction of publicly owned treatment works as authorized by section 1281 of this title, and the issuance of a permit under section 1342 of this title for the discharge of any pollutant by a new source as defined in section 1316 of this title, no action of the Administrator taken pursuant to this chapter shall be deemed a major Federal action significantly affecting the quality of the human environment within the meaning of the National Environmental Policy Act of 1969 (83 Stat. 852) [42 U.S.C. 4321 et seq.]; and"],[0,"(2) Nothing in the National Environmental Policy Act of 1969 (83 Stat. 852) shall be deemed to—"],[1,"(A) authorize any Federal agency authorized to license or permit the conduct of any activity which may result in the discharge of a pollutant into the navigable waters to review any effluent limitation or other requirement established pursuant to this chapter or the adequacy of any certification under section 1341 of this title; or"],[1,"(B) authorize any such agency to impose, as a condition precedent to the issuance of any license or permit, any effluent limitation other than any such limitation established pursuant to this chapter."],[0,"(d) Consideration of international water pollution control agreements"],[0,"Notwithstanding this chapter or any other provision of law, the Administrator (1) shall not require any State to consider in the development of the ranking in order of priority of needs for the construction of treatment works (as defined in subchapter II of this chapter), any water pollution control agreement which may have been entered into between the United States and any other nation, and (2) shall not consider any such agreement in the approval of any such priority ranking."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1371?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1371. Authority under other laws and regulations","tname":"Navigation and Navigable Waters","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 95-217","url":"https://www.govinfo.gov/link/statute/91/1566","by":{"0":"27"}},{"t":"usc","label":"16 U.S.C. § 791","url":"https://www.law.cornell.edu/uscode/text/16/791","by":{"0":"1, 2"}},{"t":"usc","label":"16 U.S.C. § 792","url":"https://www.law.cornell.edu/uscode/text/16/792","by":{"0":"2"}},{"t":"usc","label":"16 U.S.C. § 797","url":"https://www.law.cornell.edu/uscode/text/16/797","subs":["(e)"],"by":{"0":"2, 3"}},{"t":"usc","label":"16 U.S.C. § 799","url":"https://www.law.cornell.edu/uscode/text/16/799","stext":{"head":"§799. License; duration, conditions, revocation, alteration, or surrender","paras":[[0,"Licenses under this subchapter shall be issued for a period not exceeding fifty years. Each such license shall be conditioned upon acceptance by the licensee of all of the terms and conditions of this chapter and such further conditions, if any, as the Commission shall prescribe in conformity with this chapter, which said terms and conditions and the acceptance thereof shall be expressed in said license. Licenses may be revoked only for the reasons and in the manner prescribed under the provisions of this chapter, and may be altered or surrendered only upon mutual agreement between the licensee and the Commission after thirty days' public notice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/799?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§799. License; duration, conditions, revocation, alteration, or surrender","tname":"Conservation","by":{"0":"2, 9"}},{"t":"usc","label":"16 U.S.C. § 803","url":"https://www.law.cornell.edu/uscode/text/16/803","subs":["(a)(1)"],"by":{"0":"3"}},{"t":"usc","label":"16 U.S.C. § 811","url":"https://www.law.cornell.edu/uscode/text/16/811","by":{"0":"3"}},{"t":"usc","label":"16 U.S.C. § 817","url":"https://www.law.cornell.edu/uscode/text/16/817","subs":["(1)"],"stext":{"head":"§817. Projects not affecting navigable waters; necessity for Federal license, permit or right-of-way; unauthorized activities","paras":[[0,"(1) It shall be unlawful for any person, State, or municipality, for the purpose of developing electric power, to construct, operate, or maintain any dam, water conduit, reservoir, power house, or other works incidental thereto across, along, or in any of the navigable waters of the United States, or upon any part of the public lands or reservations of the United States (including the Territories), or utilize the surplus water or water power from any Government dam, except under and in accordance with the terms of a permit or valid existing right-of-way granted prior to June 10, 1920, or a license granted pursuant to this chapter. Any person, association, corporation, State, or municipality intending to construct a dam or other project works, across, along, over, or in any stream or part thereof, other than those defined in this chapter as navigable waters, and over which Congress has jurisdiction under its authority to regulate commerce with foreign nations and among the several States shall before such construction file declaration of such intention with the Commission, whereupon the Commission shall cause immediate investigation of such proposed construction to be made, and if upon investigation it shall find that the interests of interstate or foreign commerce would be affected by such proposed construction, such person, association, corporation, State, or municipality shall not construct, maintain, or operate such dam or other project works until it shall have applied for and shall have received a license under the provisions of this chapter. If the Commission shall not so find, and if no public lands or reservations are affected, permission is granted to construct such dam or other project works in such stream upon compliance with State laws."],[0,"(2) No person may commence any significant modification of any project licensed under, or exempted from, this chapter unless such modification is authorized in accordance with terms and conditions of such license or exemption and the applicable requirements of this subchapter. As used in this paragraph, the term \"commence\" refers to the beginning of physical on-site activity other than surveys or testing."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/817?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§817. Projects not affecting navigable waters; necessity for Federal license, permit or right-of-way; unauthorized activities","tname":"Conservation","by":{"0":"2"}},{"t":"law","label":"Pub. L. No. 92-500","url":"https://www.govinfo.gov/link/statute/86/816","by":{"0":"3"}},{"t":"usc","label":"33 U.S.C. § 466","url":"https://www.law.cornell.edu/uscode/text/33/466","subs":["(1964)"],"by":{"0":"3, 4"}},{"t":"usc","label":"33 U.S.C. § 466a","url":"https://www.law.cornell.edu/uscode/text/33/466a","by":{"0":"18"}},{"t":"usc","label":"33 U.S.C. § 466g","url":"https://www.law.cornell.edu/uscode/text/33/466g","subs":["(b)","(c)"],"by":{"0":"3, 3"}},{"t":"usc","label":"33 U.S.C. § 1161","url":"https://www.law.cornell.edu/uscode/text/33/1161","subs":["(1970)","(a)(2)(1970)"],"by":{"0":"19, 19"}},{"t":"usc","label":"33 U.S.C. § 1163","url":"https://www.law.cornell.edu/uscode/text/33/1163","subs":["(1970)","(a)(9)(1970)"],"by":{"0":"19, 19"}},{"t":"usc","label":"33 U.S.C. § 1171","url":"https://www.law.cornell.edu/uscode/text/33/1171","subs":["(b)(1970)"],"by":{"0":"3, 4, 18, 28"}},{"t":"usc","label":"42 U.S.C. § 4321","url":"https://www.law.cornell.edu/uscode/text/42/4321","stext":{"head":"§4321. Congressional declaration of purpose","paras":[[0,"The purposes of this chapter are: To declare a national policy which will encourage productive and enjoyable harmony between man and his environment; to promote efforts which will prevent or eliminate damage to the environment and biosphere and stimulate the health and welfare of man; to enrich the understanding of the ecological systems and natural resources important to the Nation; and to establish a Council on Environmental Quality."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4321?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4321. Congressional declaration of purpose","tname":"The Public Health and Welfare","by":{"0":"27"}},{"t":"usc","label":"33 U.S.C. § 403","url":"https://www.law.cornell.edu/uscode/text/33/403","by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 89-234","url":"https://www.govinfo.gov/link/statute/79/907","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 91-224","url":"https://www.govinfo.gov/link/statute/84/108","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","subs":["(a)"],"by":{"0":"9"}}]};